            JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true }));

        // telemetry.md
        var lines = new List<string>
        {
            "| Agent | Model | In Tok | Out Tok | Latency (ms) | Cost ($) |",
            "|-------|-------|--------|---------|--------------|----------|"
        };
        foreach (var r in snapshot)
            lines.Add($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | {r.CostUsd:F6} |");
