using System.Text.Json;

namespace MyApp.Evals.Tests;

internal sealed record TelemetryRecord(
    string AgentName, string Model, int InputTokens, int OutputTokens,
    long LatencyMs, decimal CostUsd);

internal static class TelemetryStore
{
    private static readonly List<TelemetryRecord> s_records = new();
    private static readonly object s_lock = new();

    public static void Record(TelemetryRecord r)
    {
        lock (s_lock) { s_records.Add(r); }
    }

    public static void FlushTo(string folder)
    {
        var outDir = Path.Combine(
            RepoRoot.Find(), ".copilot", "perf-reports", "evals", folder);
        Directory.CreateDirectory(outDir);

        List<TelemetryRecord> snapshot;
        lock (s_lock) { snapshot = new(s_records); }

        // telemetry.json
        File.WriteAllText(Path.Combine(outDir, "telemetry.json"),
            JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true }));

        // telemetry.md
        var lines = new List<string>
        {
            "| Agent | Model | In Tok | Out Tok | Latency (ms) | Cost ($) |",
            "|-------|-------|--------|---------|--------------|----------|"
        };
        foreach (var r in snapshot)
            lines.Add($"| {r.AgentName} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | {r.CostUsd:F6} |");
        File.WriteAllText(Path.Combine(outDir, "telemetry.md"), string.Join('\n', lines));

        Console.WriteLine($"[Telemetry] {outDir}/telemetry.md");
    }
}

