internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveAgentClient(Dictionary<string, string> modelAssignments)
    {
        // Compare mode: override model via ChatOptions.ModelId on the resolved client.
        // For now returns the same client — model assignment is applied per-call via ChatOptions.
        return ResolveAgentClient();
    }

    public static IChatClient ResolveJudgeClient(IChatClient agentClient)
    {
        var judgeOverride = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (!string.IsNullOrEmpty(judgeOverride))
        {
            // User wants a separate judge deployment (e.g., non-reasoning model).
            // Re-resolve with the override — the factory will use the same connection
            // string pattern but the judge model differs.
            return AgentChatClientFactory.Create();
        }
        // Default: judge = agent (shared cache benefits).
        return agentClient;
    }
}

