namespace MyApp.Evals.Tests;

[TestClass]
public sealed class QualityTests
{
    private static ReportingConfiguration s_reporting = null!;

    [ClassInitialize]
    public static void Init(TestContext _) =>
        s_reporting = ReportingConfig.ForQuality();

    public static IEnumerable<object[]> Golden() =>
        GoldenLoader.Load().Select(g => new object[] { g.Id, g.UserMessage, g.ReferenceResponse ?? "", g.Context ?? "" });

    [TestMethod, DynamicData(nameof(Golden), DynamicDataSourceType.Method)]
    public async Task Evaluate(string id, string userMessage, string referenceResponse, string context)
    {
        var scenarioName = $"{nameof(QualityTests)}.{id}";
        await using var run = await s_reporting.CreateScenarioRunAsync(scenarioName);

        var agent = string.IsNullOrEmpty(
            Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME"))
                ? run.ChatConfiguration!.ChatClient
                : Wire.ResolveAgentClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, RubricLoader.SystemPrompt()),
            new(ChatRole.User, userMessage),
        };
        var response = await agent.GetResponseAsync(messages);

        var contexts = new List<EvaluationContext>();
        if (!string.IsNullOrEmpty(referenceResponse))
        {
            contexts.Add(new BLEUEvaluatorContext(new[] { referenceResponse }));
            contexts.Add(new GLEUEvaluatorContext(new[] { referenceResponse }));
            contexts.Add(new F1EvaluatorContext(referenceResponse));
            contexts.Add(new EquivalenceEvaluatorContext(referenceResponse));
            contexts.Add(new CompletenessEvaluatorContext(referenceResponse));
        }
        if (!string.IsNullOrEmpty(context))
            contexts.Add(new GroundednessEvaluatorContext(context));

        await run.EvaluateAsync(messages, response, contexts);
    }
}

