// Mirror the AppHost registration. In a standalone test host we
// register the OpenAI client using the Aspire extension method that
// reads from ConnectionStrings:chat. If this package isn't available
// at test time, fall back to a direct IChatClient registration.
builder.Services.AddSingleton<IChatClient>(sp =>
{
    var config = sp.GetRequiredService<IConfiguration>();
    var connStr = config["ConnectionStrings:chat"]
        ?? throw new InvalidOperationException(
            "ConnectionStrings:chat not found in configuration.");
    // Parse connection string for Endpoint and DeploymentId
    var parts = connStr.Split(';')
        .Select(p => p.Split('=', 2))
        .Where(p => p.Length == 2)
        .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);
    parts.TryGetValue("Endpoint", out var endpoint);
    parts.TryGetValue("DeploymentId", out var deploymentId);
    parts.TryGetValue("Key", out var key);

    if (string.IsNullOrEmpty(endpoint))
        throw new InvalidOperationException("Endpoint not found in connection string.");

    var clientOptions = new Azure.AI.OpenAI.AzureOpenAIClientOptions();
    Azure.AI.OpenAI.AzureOpenAIClient azClient;
    if (!string.IsNullOrEmpty(key))
        azClient = new(new Uri(endpoint), new System.ClientModel.ApiKeyCredential(key), clientOptions);
    else
        azClient = new(new Uri(endpoint), new Azure.Identity.DefaultAzureCredential(), clientOptions);

    return azClient.GetChatClient(deploymentId ?? "chat").AsIChatClient();
});
var host = builder.Build();

